Code.Terraform:
```hcl
# SageMaker endpoint configuration with KMS encryption
resource "aws_sagemaker_endpoint_configuration" "<example_resource_name>" {
  name        = "<example_resource_name>"
  kms_key_arn = "<example_resource_arn>" # Critical: enables at-rest encryption with KMS

  production_variants {
    variant_name           = "AllTraffic"
    model_name             = "<example_resource_name>"
    instance_type          = "ml.m5.large"
    initial_instance_count = 1
  }
}
```
